// MARK: - Errors

/// Error enum for CloudSearch
public struct CloudSearchErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        /// An error occurred while processing the request.
        case baseException(CloudSearch.BaseException)
        /// The request was rejected because it attempted an operation which is not enabled.
        case disabledOperationException(CloudSearch.DisabledOperationException)
        /// An internal error occurred while processing the request. If this problem persists, report an issue from the Service Health Dashboard.
        case internalException(CloudSearch.InternalException)
        /// The request was rejected because it specified an invalid type definition.
        case invalidTypeException(CloudSearch.InvalidTypeException)
        /// The request was rejected because a resource limit has already been met.
        case limitExceededException(CloudSearch.LimitExceededException)
        /// The request was rejected because it attempted to create a resource that already exists.
        case resourceAlreadyExistsException(CloudSearch.ResourceAlreadyExistsException)
        /// The request was rejected because it attempted to reference a resource that does not exist.
        case resourceNotFoundException(CloudSearch.ResourceNotFoundException)
        /// The request was rejected because it has invalid parameters.
        case validationException(CloudSearch.ValidationException)
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "BaseException":
            let context = try singleValueContainer.decode(CloudSearch.BaseException.self)
            self.error = .baseException(context)
        case "DisabledAction":
            let context = try singleValueContainer.decode(CloudSearch.DisabledOperationException.self)
            self.error = .disabledOperationException(context)
        case "InternalException":
            let context = try singleValueContainer.decode(CloudSearch.InternalException.self)
            self.error = .internalException(context)
        case "InvalidType":
            let context = try singleValueContainer.decode(CloudSearch.InvalidTypeException.self)
            self.error = .invalidTypeException(context)
        case "LimitExceeded":
            let context = try singleValueContainer.decode(CloudSearch.LimitExceededException.self)
            self.error = .limitExceededException(context)
        case "ResourceAlreadyExists":
            let context = try singleValueContainer.decode(CloudSearch.ResourceAlreadyExistsException.self)
            self.error = .resourceAlreadyExistsException(context)
        case "ResourceNotFound":
            let context = try singleValueContainer.decode(CloudSearch.ResourceNotFoundException.self)
            self.error = .resourceNotFoundException(context)
        case "ValidationException":
            let context = try singleValueContainer.decode(CloudSearch.ValidationException.self)
            self.error = .validationException(context)
        default:
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unrecognised error code"))
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .baseException: "BaseException"
        case .disabledOperationException: "DisabledAction"
        case .internalException: "InternalException"
        case .invalidTypeException: "InvalidType"
        case .limitExceededException: "LimitExceeded"
        case .resourceAlreadyExistsException: "ResourceAlreadyExists"
        case .resourceNotFoundException: "ResourceNotFound"
        case .validationException: "ValidationException"
        }
    }
}
